/* Offline html2pdf Compatible Export Bridge (Android Native PDF + Browser Print-to-PDF) */
(function(global){
  function Html2PdfWorker(){
    this._el = null;
    this._opt = { filename: 'Document.pdf', margin: 10 };
  }
  Html2PdfWorker.prototype.from = function(el){
    this._el = typeof el === 'string' ? document.querySelector(el) : el;
    return this;
  };
  Html2PdfWorker.prototype.set = function(opt){
    this._opt = Object.assign(this._opt, opt || {});
    return this;
  };
  Html2PdfWorker.prototype.save = function(){
    const el = this._el;
    if(!el) return Promise.resolve();
    const fileName = this._opt.filename || ('Export_' + Date.now() + '.pdf');
    const htmlContent = el.innerHTML || '';
    const textContent = el.innerText || '';
    const paper = this._opt.paper || 'a4';
    const title = el.querySelector('h1,h2,h3')?.textContent?.trim() || 'مستند محاسب محترف';
    const fullDoc = window.PA_PRINT
      ? window.PA_PRINT.buildDocument(htmlContent, paper, title, 'document')
      : `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><style>body{font-family:Tahoma,Arial,sans-serif;background:#fff;color:#000;padding:14px;direction:rtl;}</style></head><body>${htmlContent}</body></html>`;

    if(window.AndroidNative && typeof window.AndroidNative.requestStorageAndSharePdfWithPaper === 'function'){
      window.AndroidNative.requestStorageAndSharePdfWithPaper(fileName, fullDoc, textContent, paper);
      return Promise.resolve();
    }
    if(window.AndroidNative && typeof window.AndroidNative.requestStorageAndSharePdf === 'function'){
      window.AndroidNative.requestStorageAndSharePdf(fileName, fullDoc, textContent);
      return Promise.resolve();
    }
    if(window.AndroidNative && typeof window.AndroidNative.sharePdfToWhatsApp === 'function'){
      window.AndroidNative.sharePdfToWhatsApp(fileName, fullDoc, textContent);
      return Promise.resolve();
    }
    if(typeof window.triggerPrint === 'function'){
      window.triggerPrint(htmlContent, paper, { fileName, title });
    } else {
      window.print();
    }
    return Promise.resolve();
  };
  global.html2pdf = function(){ return new Html2PdfWorker(); };
})(window);
